module QuantumMeasurementUnit #(
    parameter NUM_QUBITS = 8,
    parameter ADC_WIDTH = 14,
    parameter INTEGRATION_TIME_NS = 1000,
    parameter CLK_FREQ_MHZ = 250
)(
    input wire clk,
    input wire rst_n,
    input wire signed [ADC_WIDTH-1:0] adc_i [0:NUM_QUBITS-1],
    input wire signed [ADC_WIDTH-1:0] adc_q [0:NUM_QUBITS-1],
    input wire measure_trigger,
    output reg [NUM_QUBITS-1:0] measurement_result,
    output reg measurement_valid
);

localparam INTEGRATION_SAMPLES = (INTEGRATION_TIME_NS * CLK_FREQ_MHZ) / 1000;
localparam INTEGRATOR_WIDTH = $clog2(INTEGRATION_SAMPLES) + ADC_WIDTH;

reg signed [INTEGRATOR_WIDTH-1:0] integrator_i [0:NUM_QUBITS-1];
reg signed [INTEGRATOR_WIDTH-1:0] integrator_q [0:NUM_QUBITS-1];
reg [$clog2(INTEGRATION_SAMPLES):0] integration_counter;
reg measuring;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        for (int m = 0; m < NUM_QUBITS; m = m + 1) begin
            integrator_i[m] <= '0;
            integrator_q[m] <= '0;
        end
        integration_counter <= '0;
        measurement_result <= '0;
        measurement_valid <= 1'b0;
        measuring <= 1'b0;
    end else begin
        if (measure_trigger && !measuring) begin
            measuring <= 1'b1;
            integration_counter <= '0;
            for (int m = 0; m < NUM_QUBITS; m = m + 1) begin
                integrator_i[m] <= '0;
                integrator_q[m] <= '0;
            end
            measurement_valid <= 1'b0;
        end

        if (measuring) begin
            integration_counter <= integration_counter + 1;
            for (int m = 0; m < NUM_QUBITS; m = m + 1) begin
                integrator_i[m] <= integrator_i[m] + adc_i[m];
                integrator_q[m] <= integrator_q[m] + adc_q[m];
            end

            if (integration_counter == INTEGRATION_SAMPLES - 1) begin
                for (int m = 0; m < NUM_QUBITS; m = m + 1) begin
                    measurement_result[m] <= (integrator_i[m] > 0); 
                end
                measurement_valid <= 1'b1;
                measuring <= 1'b0;
            end
        end else begin
            measurement_valid <= 1'b0;
        end
    end
end
endmodule
