module quantum_controller #(
    parameter NUM_QUBITS = 8,
    parameter PULSE_WIDTH = 20,
    parameter DAC_BITS = 16,
    parameter CLK_FREQ_HZ = 100_000_000
)(
    input logic clk,
    input logic rst_n,
    input logic [31:0] gate_command,
    input logic gate_valid,
    output logic gate_ready,
    output logic signed [DAC_BITS-1:0] i_dac [NUM_QUBITS-1:0],
    output logic signed [DAC_BITS-1:0] q_dac [NUM_QUBITS-1:0],
    output logic [NUM_QUBITS-1:0] measurement_result,
    output logic measurement_valid
);

    localparam PULSE_CYCLES = (PULSE_WIDTH * (CLK_FREQ_HZ/1_000_000_000));
    localparam DELAY_CYCLES = 10;
    localparam READOUT_CYCLES = 200;

    typedef enum logic [3:0] {
        GATE_IDLE, GATE_HADAMARD, GATE_PAULI_X, GATE_PAULI_Y, GATE_PAULI_Z,
        GATE_CNOT, GATE_PHASE, GATE_RX, GATE_RY, GATE_RZ, GATE_MEASURE
    } gate_type_t;

    typedef struct packed {
        gate_type_t gate_type;
        logic [7:0] qubit_target;
        logic [7:0] qubit_control;
        logic [15:0] angle;
    } gate_instruction_t;

    gate_instruction_t current_gate;
    logic [$clog2(PULSE_CYCLES):0] pulse_counter;
    logic [$clog2(READOUT_CYCLES):0] delay_counter;

    logic signed [DAC_BITS:0] nco_phase [NUM_QUBITS-1:0];
    logic signed [DAC_BITS:0] nco_freq [NUM_QUBITS-1:0];
    logic [DAC_BITS-1:0] amplitude [NUM_QUBITS-1:0];

    typedef enum logic [2:0] {
        FSM_IDLE, FSM_LOAD_GATE, FSM_GENERATE_PULSE, FSM_WAIT_DELAY, FSM_READOUT, FSM_COMPLETE
    } fsm_state_t;
    fsm_state_t state, next_state;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) state <= FSM_IDLE;
        else state <= next_state;
    end

    always_comb begin
        next_state = state;
        case (state)
            FSM_IDLE: if (gate_valid) next_state = FSM_LOAD_GATE;
            FSM_LOAD_GATE: next_state = FSM_GENERATE_PULSE;
            FSM_GENERATE_PULSE: if (pulse_counter == PULSE_CYCLES - 1) next_state = FSM_WAIT_DELAY;
            FSM_WAIT_DELAY: if (delay_counter == DELAY_CYCLES - 1) next_state = (current_gate.gate_type == GATE_MEASURE) ? FSM_READOUT : FSM_COMPLETE;
            FSM_READOUT: if (delay_counter == READOUT_CYCLES - 1) next_state = FSM_COMPLETE;
            FSM_COMPLETE: next_state = FSM_IDLE;
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            current_gate <= '0;
            pulse_counter <= '0;
            delay_counter <= '0;
            gate_ready <= 1'b1;
        end else begin
            gate_ready <= (state == FSM_IDLE);
            if (state == FSM_IDLE) begin
                pulse_counter <= '0;
                delay_counter <= '0;
            end
            if (state == FSM_LOAD_GATE) begin
                current_gate <= gate_command;
            end
            if (state == FSM_GENERATE_PULSE) begin
                pulse_counter <= pulse_counter + 1;
            end
            if (state == FSM_WAIT_DELAY || state == FSM_READOUT) begin
                delay_counter <= delay_counter + 1;
            end
        end
    end

    generate
        for (genvar i = 0; i < NUM_QUBITS; i++) begin : nco_gen
            initial nco_freq[i] = 16'd5000 + (i * 16'd100);
            always_ff @(posedge clk or negedge rst_n) begin
                if (!rst_n) begin
                    nco_phase[i] <= '0;
                    amplitude[i] <= '0;
                end else begin
                    nco_phase[i] <= nco_phase[i] + nco_freq[i];
                    amplitude[i] <= '0;
                    if (state == FSM_GENERATE_PULSE && current_gate.qubit_target == i) begin
                        case (current_gate.gate_type)
                            GATE_HADAMARD: amplitude[i] <= 16'h7FFF;
                            GATE_PAULI_X:  amplitude[i] <= 16'hFFFF;
                            GATE_PAULI_Y:  amplitude[i] <= 16'hFFFF;
                            GATE_RX:       amplitude[i] <= current_gate.angle;
                            GATE_RY:       amplitude[i] <= current_gate.angle;
                            default:       amplitude[i] <= '0;
                        endcase
                    end
                end
            end
        end
    endgenerate

    generate
        for (genvar i = 0; i < NUM_QUBITS; i++) begin : dac_gen
            logic signed [DAC_BITS-1:0] sin_val, cos_val;
            cordic_sin_cos #(.WIDTH(DAC_BITS)) cordic_inst (
                .clk(clk), .rst_n(rst_n), .phase_in(nco_phase[i]), .sin_out(sin_val), .cos_out(cos_val));
            always_ff @(posedge clk) begin
                i_dac[i] <= (cos_val * $signed(amplitude[i])) >>> DAC_BITS;
                q_dac[i] <= (sin_val * $signed(amplitude[i])) >>> DAC_BITS;
            end
        end
    endgenerate

    localparam INTEGRATOR_WIDTH = $clog2(READOUT_CYCLES) + DAC_BITS;
    logic signed [INTEGRATOR_WIDTH-1:0] readout_integrator_i [NUM_QUBITS-1:0];
    logic signed [INTEGRATOR_WIDTH-1:0] readout_integrator_q [NUM_QUBITS-1:0];
    logic [$clog2(READOUT_CYCLES):0] readout_counter;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (int j = 0; j < NUM_QUBITS; j++) begin
                readout_integrator_i[j] <= '0;
                readout_integrator_q[j] <= '0;
            end
            measurement_result <= '0;
            measurement_valid <= 1'b0;
            readout_counter <= '0;
        end else begin
            measurement_valid <= 1'b0;
            if (state == FSM_READOUT) begin
                readout_counter <= readout_counter + 1;
                for (int j = 0; j < NUM_QUBITS; j++) begin
                    readout_integrator_i[j] <= readout_integrator_i[j] + i_dac[j];
                    readout_integrator_q[j] <= readout_integrator_q[j] + q_dac[j];
                end
                if (readout_counter == READOUT_CYCLES - 1) begin
                    for (int j = 0; j < NUM_QUBITS; j++) begin
                        measurement_result[j] <= (readout_integrator_i[j] > 0);
                    end
                    measurement_valid <= 1'b1;
                end
            end else begin
                readout_counter <= '0;
                for (int j = 0; j < NUM_QUBITS; j++) begin
                    readout_integrator_i[j] <= '0;
                    readout_integrator_q[j] <= '0;
                end
            end
        end
    end
endmodule

module cordic_sin_cos #(parameter WIDTH = 16, parameter STAGES = 16)(
    input logic clk,
    input logic rst_n,
    input logic signed [WIDTH-1:0] phase_in,
    output logic signed [WIDTH-1:0] sin_out,
    output logic signed [WIDTH-1:0] cos_out
);
    logic signed [WIDTH-1:0] x_pipe [STAGES];
    logic signed [WIDTH-1:0] y_pipe [STAGES];
    logic signed [WIDTH-1:0] z_pipe [STAGES];
    logic [WIDTH-1:0] atan_lut [STAGES-1:0];

    initial begin
        atan_lut[0] = 16'h2000; atan_lut[1] = 16'h12E4; atan_lut[2] = 16'h09FB; atan_lut[3] = 16'h0511;
        atan_lut[4] = 16'h028B; atan_lut[5] = 16'h0146; atan_lut[6] = 16'h00A3; atan_lut[7] = 16'h0051;
        atan_lut[8] = 16'h0029; atan_lut[9] = 16'h0014; atan_lut[10] = 16'h000A; atan_lut[11] = 16'h0005;
        atan_lut[12] = 16'h0003; atan_lut[13] = 16'h0001; atan_lut[14] = 16'h0001; atan_lut[15] = 16'h0000;
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for(int i=0; i<STAGES; i++) begin
                x_pipe[i] <= '0; y_pipe[i] <= '0; z_pipe[i] <= '0;
            end
        end else begin
            x_pipe[0] <= 16'h4DBA; 
            y_pipe[0] <= 0;
            z_pipe[0] <= phase_in;
            for (int i = 0; i < STAGES - 1; i++) begin
                if (z_pipe[i][WIDTH-1]) begin
                    x_pipe[i+1] <= x_pipe[i] + (y_pipe[i] >>> i);
                    y_pipe[i+1] <= y_pipe[i] - (x_pipe[i] >>> i);
                    z_pipe[i+1] <= z_pipe[i] + atan_lut[i];
                end else begin
                    x_pipe[i+1] <= x_pipe[i] - (y_pipe[i] >>> i);
                    y_pipe[i+1] <= y_pipe[i] + (x_pipe[i] >>> i);
                    z_pipe[i+1] <= z_pipe[i] - atan_lut[i];
                end
            end
        end
    end
    assign cos_out = x_pipe[STAGES-1];
    assign sin_out = y_pipe[STAGES-1];
endmodule
