import numpy as np
from dataclasses import dataclass
import json

@dataclass
class WaveguidePhysics:
    wavelengthnm: float = 1550.0
    ncore: float = 3.48
    nclad: float = 1.445
    corewidthnm: float = 450.0
    coreheightnm: float = 220.0
    lossdbcm: float = 0.3
    groupindex: float = 4.2
    n2m2w: float = 1.2e-17
    beta2ps2km: float = -1.2

    def effective_index(self) -> float:
        k0 = 2 * np.pi / (self.wavelengthnm * 1e-9)
        V = k0 * (self.corewidthnm * 1e-9) * np.sqrt(self.ncore**2 - self.nclad**2)
        b = (V**2 / (2 + V**2)) # Approximation for strip waveguide
        neff = np.sqrt(self.nclad**2 + b * (self.ncore**2 - self.nclad**2))
        return neff

    def propagation_constant(self) -> float:
        neff = self.effective_index()
        beta = 2 * np.pi * neff / (self.wavelengthnm * 1e-9)
        return beta

    def nonlinearlength(self, powermw: float) -> float:
        gamma = (2 * np.pi * self.n2m2w) / (self.wavelengthnm * 1e-9 * 0.12e-12)
        LNL = 1 / (gamma * powermw * 1e-3)
        return LNL

@dataclass
class MicroringResonator:
    radiusum: float = 5.0
    gapnm: float = 200.0
    Qfactor: float = 50000.0
    fsrghz: float = 20.0
    neff: float = 2.5
    dndT: float = 1.86e-4
    wavelengthnm: float = 1550.0
    couplingcoefficient: float = 0.1

    def resonant_wavelengths(self, num_resonances: int = 10) -> np.ndarray:
        c = 299792458
        ng = 4.2 
        circumference = 2 * np.pi * self.radiusum * 1e-6
        m0 = int((ng * circumference) / (self.wavelengthnm * 1e-9))
        m = np.arange(m0 - num_resonances//2, m0 + num_resonances//2)
        resonances = (ng * circumference) / m
        return resonances * 1e9

    def coupling_efficiency(self) -> float:
        return self.couplingcoefficient

    def transmission_spectrum(self, wavelengthsnm: np.ndarray) -> np.ndarray:
        kappa = np.sqrt(self.couplingcoefficient)
        linewidth_ghz = self.fsrghz / self.Qfactor
        lambda_res = self.resonant_wavelengths(1)[0]
        c_ghz_nm = 299792.458 / 1e-3
        detuning_ghz = c_ghz_nm * (1/lambda_res - 1/wavelengthsnm)
        lorentzian = (1 - kappa**2) / (1 - 2j * detuning_ghz / linewidth_ghz)
        return np.abs(lorentzian)**2

    def thermal_tuning(self, heater_power_mw: float) -> float:
        Rth = 1500.0
        deltaT = heater_power_mw * 1e-3 * Rth
        delta_lambda = self.wavelengthnm * self.dndT * deltaT / self.neff
        return delta_lambda

@dataclass
class PhotonicNeuralAccelerator:
    num_wavelengths: int = 16
    mzi_size: int = 8

    def mzi_transfer_function(self, phase_rad: float, splitting_ratio: float = 0.5) -> float:
        return np.cos(phase_rad/2)**2

    def matrix_multiply(self, input_vector: np.ndarray, phase_matrix: np.ndarray) -> np.ndarray:
        mzi_outputs = np.zeros((self.mzi_size, self.mzi_size))
        for i in range(self.mzi_size):
            for j in range(self.mzi_size):
                input_val = input_vector[i % self.num_wavelengths]
                phase = phase_matrix[i,j]
                mzi_outputs[i, j] = input_val * self.mzi_transfer_function(phase)
        photodetector_currents = np.sum(mzi_outputs, axis=0) * 1.1 # responsivity
        return photodetector_currents

    def add_noise(self, signal: np.ndarray, osnr_db: float = 35) -> np.ndarray:
        osnr_linear = 10**(osnr_db / 10)
        signal_power = np.mean(signal**2)
        noise_power = signal_power / osnr_linear
        noise = np.random.normal(0, np.sqrt(noise_power), signal.shape)
        return signal + noise

@dataclass
class CoherentOpticalLink:
    symbolrategbaud: float = 28.0
    laserlinewidthkhz: float = 100.0
    osnrdb: float = 35.0
    constellation: np.ndarray = np.array([-3-3j, -3-1j, -3+3j, -3+1j, -1-3j, -1-1j, -1+3j, -1+1j, 3-3j, 3-1j, 3+3j, 3+1j, 1-3j, 1-1j, 1+3j, 1+1j]) / np.sqrt(10)

    def modulate(self, bits: np.ndarray) -> np.ndarray:
        bits_per_symbol = int(np.log2(len(self.constellation)))
        num_symbols = len(bits) // bits_per_symbol
        symbols = np.zeros(num_symbols, dtype=np.complex128)
        for i in range(num_symbols):
            symbol_bits = bits[i*bits_per_symbol:(i+1)*bits_per_symbol]
            symbol_index = int("".join(symbol_bits.astype(str)), 2)
            symbols[i] = self.constellation[symbol_index]
        return symbols

    def add_phase_noise(self, symbols: np.ndarray) -> np.ndarray:
        dt = 1 / (self.symbolrategbaud * 1e9)
        linewidth_hz = self.laserlinewidthkhz * 1e3
        variance = 2 * np.pi * linewidth_hz * dt
        phase_noise = np.cumsum(np.random.normal(0, np.sqrt(variance), len(symbols)))
        return symbols * np.exp(1j * phase_noise)
