import spinal.core._
import spinal.lib._
import spinal.lib.fsm._

case class QuantumGateInstruction() extends Bundle {
    val gateType = UInt(4 bits)
    val qubitTarget = UInt(8 bits)
    val qubitControl = UInt(8 bits)
    val angle = UInt(16 bits)
}

case class QuantumControllerConfig(
    numQubits: Int = 8,
    pulseWidthCycles: Int = 2,
    dacBits: Int = 16
)

class QuantumController(config: QuantumControllerConfig) extends Component {
    val io = new Bundle {
        val gateCommand = in(QuantumGateInstruction())
        val gateValid = in Bool()
        val gateReady = out Bool()
        val iDac = out Vec(SInt(config.dacBits bits), config.numQubits)
        val qDac = out Vec(SInt(config.dacBits bits), config.numQubits)
        val measurementResult = out(Bits(config.numQubits bits))
        val measurementValid = out Bool()
    }

    val currentGate = Reg(QuantumGateInstruction())
    val pulseCounter = Reg(UInt(log2Up(config.pulseWidthCycles) bits)) init(0)
    val gateDelayCounter = Reg(UInt(8 bits)) init(0)
    val ncoPhase = Vec(Reg(UInt(16 bits)) init(0), config.numQubits)
    val ncoFreq = Vec.fill(config.numQubits)(Reg(UInt(16 bits)))
    val amplitude = Vec(Reg(UInt(16 bits)) init(0), config.numQubits)

    for(i <- 0 until config.numQubits) {
        ncoFreq(i) init(U(5000 + i * 100, 16 bits))
    }

    val fsm = new StateMachine {
        val IDLE = new State with EntryPoint
        val LOAD_GATE = new State
        val GENERATE_PULSE = new State
        val WAIT_DELAY = new State
        val READOUT = new State
        val COMPLETE = new State

        IDLE.whenIsActive {
            io.gateReady := True
            when(io.gateValid) {
                goto(LOAD_GATE)
            }
        }
        LOAD_GATE.onEntry(pulseCounter := 0, gateDelayCounter := 0)
        LOAD_GATE.whenIsActive {
            currentGate := io.gateCommand
            io.gateReady := False
            goto(GENERATE_PULSE)
        }
        GENERATE_PULSE.whenIsActive {
            pulseCounter := pulseCounter + 1
            when(pulseCounter === config.pulseWidthCycles - 1) {
                goto(WAIT_DELAY)
            }
        }
        WAIT_DELAY.whenIsActive {
            gateDelayCounter := gateDelayCounter + 1
            when(gateDelayCounter === 99) {
                when(currentGate.gateType === 10) { goto(READOUT) } otherwise { goto(COMPLETE) }
            }
        }
        READOUT.onEntry(gateDelayCounter := 0)
        READOUT.whenIsActive {
            gateDelayCounter := gateDelayCounter + 1
            when(gateDelayCounter === 199) {
              goto(COMPLETE)
            }
        }
        COMPLETE.whenIsActive {
            goto(IDLE)
        }
    }

    for(i <- 0 until config.numQubits) {
        ncoPhase(i) := ncoPhase(i) + ncoFreq(i)
        amplitude(i) := 0
        when(fsm.isActive(fsm.GENERATE_PULSE) && currentGate.qubitTarget === i) {
            switch(currentGate.gateType) {
                is(1) { amplitude(i) := 0x7FFF } // HADAMARD
                is(2) { amplitude(i) := 0xFFFF } // PAULI-X
                is(3) { amplitude(i) := 0xFFFF } // PAULI-Y
                is(7) { amplitude(i) := currentGate.angle } // RX
                is(8) { amplitude(i) := currentGate.angle } // RY
            }
        }
    }

    for(i <- 0 until config.numQubits) {
        val cordic = new CordicSinCos(16, 16)
        cordic.io.phase := ncoPhase(i)
        io.iDac(i) := (cordic.io.cos * amplitude(i).asSInt).resize(config.dacBits)
        io.qDac(i) := (cordic.io.sin * amplitude(i).asSInt).resize(config.dacBits)
    }

    val readoutIntegratorI = Vec(Reg(SInt(32 bits)) init(0), config.numQubits)
    val readoutIntegratorQ = Vec(Reg(SInt(32 bits)) init(0), config.numQubits)
    val readoutCounter = Reg(UInt(8 bits)) init(0)
    io.measurementValid := False

    when(fsm.isActive(fsm.READOUT)) {
        readoutCounter := readoutCounter + 1
        for(i <- 0 until config.numQubits) {
            readoutIntegratorI(i) := readoutIntegratorI(i) + io.iDac(i).resize(32 bits)
            readoutIntegratorQ(i) := readoutIntegratorQ(i) + io.qDac(i).resize(32 bits)
        }
        when(readoutCounter === 199) {
            for(i <- 0 until config.numQubits) {
                val mag_sq = (readoutIntegratorI(i) * readoutIntegratorI(i)) + (readoutIntegratorQ(i) * readoutIntegratorQ(i))
                io.measurementResult(i) := mag_sq > S(0x10000000, 64 bits)
            }
            io.measurementValid := True
        }
    } otherwise {
        readoutCounter := 0
        for(i <- 0 until config.numQubits) {
            readoutIntegratorI(i) := 0
            readoutIntegratorQ(i) := 0
        }
    }
}

class CordicSinCos(width: Int, stages: Int) extends Component {
  val io = new Bundle {
    val phase = in UInt(width bits)
    val sin = out SInt(width bits)
    val cos = out SInt(width bits)
  }

  val atanLut = Vec(
    S(2048*4, width bits), S(1189*4, width bits), S(613*4, width bits), S(309*4, width bits), S(155*4, width bits), 
    S(77*4, width bits), S(39*4, width bits), S(19*4, width bits), S(10*4, width bits), S(5*4, width bits), 
    S(2*4, width bits), S(1*4, width bits), S(0, width bits), S(0, width bits), S(0, width bits), S(0, width bits)
  )

  val x = Vec(SInt(width bits), stages)
  val y = Vec(SInt(width bits), stages)
  val z = Vec(SInt(width bits), stages)

  x(0) := S(19172, width bits) // 0.585 * 2^15
  y(0) := S(0, width bits)
  z(0) := io.phase.asSInt

  var currentX = x(0)
  var currentY = y(0)
  var currentZ = z(0)

  for(i <- 0 until stages -1) {
    val nextX = RegNext(Mux(currentZ.msb, currentX + (currentY >> i), currentX - (currentY >> i)))
    val nextY = RegNext(Mux(currentZ.msb, currentY - (currentX >> i), currentY + (currentX >> i)))
    val nextZ = RegNext(Mux(currentZ.msb, currentZ + atanLut(i), currentZ - atanLut(i)))
    currentX = nextX
    currentY = nextY
    currentZ = nextZ
  }

  io.cos := RegNext(currentX)
  io.sin := RegNext(currentY)
}
