module SpinTransferTorqueDevice #(
    parameter CRITICAL_CURRENT_UA = 50,
    parameter SWITCHING_TIME_NS = 2,
    parameter TMR_RATIO_FP = 2560,
    parameter CLK_FREQ_HZ = 1_000_000_000
)(
    input wire clk,
    input wire rst_n,
    input wire [15:0] spin_current_ua,
    input wire write_enable,
    output reg magnetization_state,
    output reg [15:0] resistance_ohm,
    output reg switching_complete
);

localparam SPIN_POLARIZATION_FP = 717; // 0.7 in Q10
localparam FP_SHIFT = 10;
localparam SWITCHING_CYCLES = SWITCHING_TIME_NS * (CLK_FREQ_HZ / 1_000_000_000);

reg [31:0] spin_torque_magnitude;
reg [15:0] switching_counter;
reg switching_in_progress;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        magnetization_state <= 1'b0;
        resistance_ohm <= 16'd1000;
        switching_complete <= 1'b0;
        switching_counter <= '0;
        switching_in_progress <= 1'b0;
    end else begin
        spin_torque_magnitude <= (spin_current_ua * SPIN_POLARIZATION_FP) >>> FP_SHIFT;
        switching_complete <= 1'b0;
        if (write_enable && (spin_current_ua > CRITICAL_CURRENT_UA) && !switching_in_progress) begin
            switching_in_progress <= 1'b1;
            switching_counter <= '0;
        end

        if (switching_in_progress) begin
            if (switching_counter == SWITCHING_CYCLES - 1) begin
                magnetization_state <= ~magnetization_state;
                switching_in_progress <= 1'b0;
                switching_complete <= 1'b1;
                switching_counter <= '0;
            end else begin
                switching_counter <= switching_counter + 1;
            end
        end

        if (magnetization_state)
            resistance_ohm <= 16'd1000;
        else
            resistance_ohm <= 16'd1000 + ((16'd1000 * TMR_RATIO_FP) >>> FP_SHIFT);
    end
end
endmodule

module MagneticDomainWallMemory #(
    parameter NUM_DOMAINS = 64,
    parameter DOMAIN_WIDTH_NM = 100,
    parameter WALL_VELOCITY_M_S = 100
)(
    input wire clk,
    input wire rst_n,
    input wire [5:0] address,
    input wire data_in,
    input wire write_enable,
    input wire read_enable,
    input wire [15:0] drive_current_ua,
    output reg data_out,
    output reg access_ready
);

localparam WALL_PROPAGATION_TIME_NS = (DOMAIN_WIDTH_NM * 1.0) / (WALL_VELOCITY_M_S);
localparam ACCESS_CYCLES = (WALL_PROPAGATION_TIME_NS > 1) ? WALL_PROPAGATION_TIME_NS : 1;

reg [NUM_DOMAINS-1:0] domain_states;
reg [$clog2(ACCESS_CYCLES):0] access_counter;
reg access_in_progress;
reg [5:0] wall_position;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        domain_states <= '0;
        data_out <= 1'b0;
        access_ready <= 1'b1;
        wall_position <= '0;
        access_counter <= '0;
        access_in_progress <= 1'b0;
    end else begin
        if (write_enable && access_ready && (drive_current_ua > 20)) begin
            access_in_progress <= 1'b1;
            access_ready <= 1'b0;
            access_counter <= '0;
            wall_position <= address;
        end

        if (read_enable && access_ready) begin
            data_out <= domain_states[address];
        end

        if (access_in_progress) {
            if (access_counter == ACCESS_CYCLES - 1) begin
                domain_states[wall_position] <= data_in;
                access_in_progress <= 1'b0;
                access_ready <= 1'b1;
            end
            access_counter <= access_counter + 1;
        }
    end
end
