from dataclasses import dataclass
import numpy as np

hbar = 1.054571817e-34
echarge = 1.602176634e-19
mu0 = 4 * np.pi * 1e-7
kB = 1.381e-23
T = 300

@dataclass
class SpinTransferTorquePhysics:
    spin_polarization_percent: float = 70.0
    critical_current_density_macm2: float = 5.0
    switching_time_ns: float = 2.0
    tmr_ratio: float = 2.5
    gilbert_damping_constant: float = 0.01
    saturation_magnetization_kam: float = 800.0
    magneticanisotropyfield_oe: float = 500.0
    freelayer_thickness_nm: float = 2.0

    def critical_current_density(self) -> float:
        Ms = self.saturation_magnetization_kam * 1e3
        Hk = self.magneticanisotropyfield_oe * 1000 / (4 * np.pi)
        t = self.freelayer_thickness_nm * 1e-9
        alpha = self.gilbert_damping_constant
        P = self.spin_polarization_percent / 100.0
        Jc0 = (2 * echarge * alpha * Ms * t / (hbar * P)) * (Hk + 0.5 * Ms)
        return Jc0 / 1e10

    def switching_probability(self, current_density_ma_cm2: float, pulse_duration_ns: float) -> float:
        tau_0 = 1e-9
        Ms = self.saturation_magnetization_kam * 1e3
        Hk = self.magneticanisotropyfield_oe * 1000 / (4 * np.pi)
        V = 1e-21 
        E_barrier = 0.5 * mu0 * Ms * Hk * V
        I_ratio = current_density_ma_cm2 / self.critical_current_density_macm2
        if I_ratio >= 1: return 1.0
        thermal_factor = E_barrier / (kB * T)
        time_factor = pulse_duration_ns * 1e-9 / tau_0
        P_switch = 1 - np.exp(-time_factor * np.exp(-thermal_factor * (1 - I_ratio)**2))
        return P_switch

    def resistance(self, magnetization_parallel: bool) -> float:
        R_min = 1000.0
        if magnetization_parallel:
            return R_min
        else:
            return R_min * (1 + self.tmr_ratio)

@dataclass
class SpinHallEffectPhysics:
    spinhallangle: float = 0.3
    spindiffusionlengthnm: float = 5.0
    fermivelocitykms: float = 1500.0

    def spin_current_density(self, charge_current_ma_cm2: float) -> float:
        return self.spinhallangle * charge_current_ma_cm2

    def spin_accumulation(self, Jc_ma_cm2: float, thickness_nm: float) -> float:
        tau_sf = self.spindiffusionlengthnm * 1e-9 / (self.fermivelocitykms * 1e3)
        mu_s = (hbar / (2 * echarge)) * self.spinhallangle * Jc_ma_cm2 * 1e4 * tau_sf
        return mu_s

