class MagneticDomainWallPhysics:
    domain_width_nm: float = 100.0
    wall_width_nm: float = 10.0
    wall_velocity_ms: float = 100.0
    depinning_field_oe: float = 50.0
    perpendicular_anisotropy_kjm3: float = 800.0
    gilbert_damping: float = 0.01

    def wall_energy(self) -> float:
        A_ex = 13e-12
        sigma_wall = 4 * np.sqrt(A_ex * self.perpendicular_anisotropy_kjm3 * 1e3)
        return sigma_wall

    def walker_breakdown_field(self) -> float:
        Ms = 800e3
        H_walker = self.gilbert_damping * Ms / 2
        return H_walker / (1000 / (4*np.pi))

    def domain_wall_velocity(self, H_drive_oe: float, J_c_ma_cm2: float) -> float:
        mu_wall = self.wall_velocity_ms / (200 - self.depinning_field_oe)
        v_field = mu_wall * max(0, H_drive_oe - self.depinning_field_oe)
        return v_field

